// Discrimina entre cliente nuevo y cliente recurrente (Retargeting)
const body = items[0].json.body;
const customerOrdersCount = body.customer ? body.customer.orders_count : 1;
const isNewCustomer = customerOrdersCount <= 1;
const utmSource = body.note_attributes ? (body.note_attributes.find(a => a.name === 'utm_source') || {}).value : 'directo';

return [{
  json: {
    order_id: body.id,
    customer_email: body.email,
    total_price: parseFloat(body.total_price || 34.00),
    is_new_customer: isNewCustomer,
    utm_source: utmSource,
    channel_clean: isNewCustomer && utmSource && utmSource.includes('meta') ? 'META_ACQUISITION' : (isNewCustomer ? 'ORGANIC' : 'REPEAT_BUYER_RETARGETING')
  }
}];
